package com.rotarypumpers.meraki.core;
import org.json.*;import java.util.*;
/** Read-only presentation of fresh observed targets; never treats a saved receipt as live. */
public final class RecordPresentation{
 public static boolean fresh(boolean connected,boolean foreground,long sampleAt,long now){return connected&&foreground&&sampleAt>0&&now>=sampleAt&&now-sampleAt<3000;}
 public static boolean locked(Sample s,Recorder.State state){return s!=null&&(s.active||GrindWorkflow.grinding(s)||s.registers[24]==1||(s.registers[33]&0x4000)!=0||state==Recorder.State.TARING||state==Recorder.State.SETTLING);}
 public static boolean canAdjust(boolean fresh,Sample s,Recorder.State state){return fresh&&s!=null&&state==Recorder.State.READY&&!locked(s,state)&&s.idle();}
 public static boolean matches(JSONObject recipe,Sample s){if(recipe==null||s==null)return false;String mode=recipe.optString("preinfusion_mode","keep");return Math.abs(recipe.optDouble("dose_g",Double.NaN)-s.registers[4]/10.0)<.00001&&Math.abs(recipe.optDouble("yield_g",Double.NaN)-s.registers[23]/10.0)<.00001&&Math.abs(recipe.optDouble("brew_c",Double.NaN)-(s.registers[11]/10.0+5))<.00001&&(mode.equals("keep")||mode.equals("on")&&s.preferences[0]==1||mode.equals("off")&&s.preferences[0]==0);}
 public static String targets(JSONObject r){return r==null?"Choose a recipe":String.format(Locale.US,"%.1f → %.1f g · %.0f°C · grind %d",r.optDouble("dose_g"),r.optDouble("yield_g"),r.optDouble("brew_c"),r.optInt("grind"));}
 public static String observed(Sample s){return s==null?"Machine settings not checked":String.format(Locale.US,"%.1f → %.1f g · %.0f°C · pre-infusion %s",s.registers[4]/10.0,s.registers[23]/10.0,s.registers[11]/10.0+5,s.preferences[0]==1?"on":"off");}
 public static JSONObject reference(JSONObject recipe,Sample actual,JSONArray shots){if(recipe==null)return null;JSONObject best=null;for(int i=0;i<shots.length();i++){JSONObject s=shots.optJSONObject(i);if(s==null||!s.optBoolean("favourite")||!s.optBoolean("complete")||!Double.isFinite(ShotInsights.average(s)))continue;JSONObject sr=s.optJSONObject("recipe");if(sr==null||!recipe.optString("id").equals(sr.optString("id")))continue;double dose=actual==null?recipe.optDouble("dose_g"):actual.registers[4]/10.0,yield=actual==null?recipe.optDouble("yield_g"):actual.registers[23]/10.0,temp=actual==null?recipe.optDouble("brew_c"):actual.registers[11]/10.0+5;int grind=actual==null?recipe.optInt("grind"):actual.registers[37];if(s.optDouble("dose_target_g")!=dose||s.optDouble("yield_target_g")!=yield||s.optDouble("brew_target_c")!=temp||s.optInt("grind_setting")!=grind)continue;JSONObject pi=s.optJSONObject("pre_infusion");if(pi==null)continue;if(actual!=null){if(pi.optInt("enabled",-1)!=actual.preferences[0]||pi.optInt("pressure_choice",-1)!=Sample.u32(actual.preferences,1)||pi.optInt("duration_setting_s",-1)!=Sample.u32(actual.preferences,5))continue;}else{String mode=recipe.optString("preinfusion_mode","keep");if(mode.equals("on")&&pi.optInt("enabled")!=1||mode.equals("off")&&pi.optInt("enabled")!=0)continue;}if(best==null||s.optString("start_utc").compareTo(best.optString("start_utc"))>0)best=s;}return best;}
}
